   882	    HTTP_APPEND("POST %s HTTP/1.1\r\n", path);
   883	    HTTP_APPEND("Host: %s\r\n", host);
   884	    HTTP_APPEND("Content-Type: application/json\r\n");
   885	    HTTP_APPEND("Connection: close\r\n");
   886	    HTTP_APPEND("User-Agent: agent/1.0\r\n");
