{
    strncpy(host, AGENT_MIMO_VOICE_HOST, host_cap - 1);
    strncpy(path, AGENT_MIMO_VOICE_PATH, path_cap - 1);

    /* ASR/TTS are served by the token-plan endpoint.  Do not inherit the
