    const char *name;

    /* Load credentials from config store. */
    int (*init)(void);

    /* Recognize PCM audio (16-bit LE, 16kHz, mono) into text. */
    int (*recognize)(const unsigned char *pcm_data,
                     size_t pcm_len,
                     char *text_out,
                     size_t text_cap);

    /* Release resources held by the backend. */
    void (*deinit)(void);
} voice_asr_ops_t;

