    first = cJSON_GetArrayItem(choices, 0);
    message = cJSON_GetObjectItemCaseSensitive(first, "message");
    audio = message ? cJSON_GetObjectItemCaseSensitive(message, "audio") : NULL;
    data = audio ? cJSON_GetObjectItemCaseSensitive(audio, "data") : NULL;
    if (!cJSON_IsString(data) || !data->valuestring
        || data->valuestring[0] == '\0') {
        return -EPROTO;
    }

    *data_out = data->valuestring;
    return 0;
}

