    void* user_data)
{
    if (!s_active) {
        syslog(LOG_ERR, "[%s] No TTS backend for streaming\n", TAG);
        return -ENODEV;
    }

    if (s_active->stream_synthesize) {
        return s_active->stream_synthesize(text, cb, user_data);
    }

    /* Batch-only backends are delivered as one PCM chunk. */
    unsigned char *pcm = malloc(AGENT_VOICE_RESP_BUF_SIZE);
    size_t pcm_len = 0;
    if (!pcm) {
        return -ENOMEM;
    }

    int ret = s_active->synthesize(text, pcm,
        AGENT_VOICE_RESP_BUF_SIZE, &pcm_len);
    if (ret == 0 && pcm_len > 0 && cb) {
        cb(pcm, pcm_len, 1, user_data);
    }
    free(pcm);
    return ret;
}
