static int mimo_asr_init(void)
{
    char key[256] = { 0 };
    int ret = get_api_key(key, sizeof(key));
    memset(key, 0, sizeof(key));
    if (ret < 0) {
        syslog(LOG_WARNING, "[%s] ASR API key is not configured\n", TAG);
    }
    return 0;
}

static int mimo_asr_recognize(const unsigned char *pcm_data,
                              size_t pcm_len,
                              char *text_out,
                              size_t text_cap)
{
    char *body = NULL;
    char *response = NULL;
    cJSON *root = NULL;
    int ret;

    if (!pcm_data || pcm_len == 0 || !text_out || text_cap == 0) {
        return -EINVAL;
    }
    if (pcm_len > AGENT_MIMO_MAX_AUDIO_BYTES) {
        return -EFBIG;
    }

    ret = make_asr_body(pcm_data, pcm_len, &body);
    if (ret < 0) {
        return ret;
    }

    response = calloc(1, AGENT_MIMO_HTTP_RESP_BYTES);
    if (!response) {
        free(body);
        return -ENOMEM;
    }

    ret = post_mimo(body, response, AGENT_MIMO_HTTP_RESP_BYTES);
    free(body);
    if (ret < 0) {
        free(response);
        return ret;
    }

    root = cJSON_Parse(response);
    free(response);
    if (!root) {
        return -EPROTO;
    }

    ret = json_string(root, "content", text_out, text_cap);
    cJSON_Delete(root);
    if (ret == 0) {
        syslog(LOG_INFO, "[%s] ASR recognized %zu bytes\n", TAG, pcm_len);
    }
    return ret;
}

static int make_tts_body(const char *text, char **body_out)
{
    cJSON *root = cJSON_CreateObject();
    cJSON *messages = cJSON_CreateArray();
    cJSON *message = cJSON_CreateObject();
    cJSON *audio = cJSON_CreateObject();
    char *body;

    if (!root || !messages || !message || !audio) {
        cJSON_Delete(root);
        cJSON_Delete(messages);
        cJSON_Delete(message);
        cJSON_Delete(audio);
        return -ENOMEM;
    }

    cJSON_AddStringToObject(root, "model", AGENT_MIMO_TTS_MODEL);
    cJSON_AddStringToObject(message, "role", "assistant");
    cJSON_AddStringToObject(message, "content", text);
    cJSON_AddItemToArray(messages, message);
    cJSON_AddItemToObject(root, "messages", messages);
    cJSON_AddStringToObject(audio, "format", "wav");
    cJSON_AddStringToObject(audio, "voice", AGENT_MIMO_TTS_VOICE);
    cJSON_AddItemToObject(root, "audio", audio);

    body = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);
    if (!body) {
        return -ENOMEM;
    }
    *body_out = body;
    return 0;
}

static int extract_wav_pcm(const unsigned char *wav, size_t wav_len,
                           unsigned char *pcm_out, size_t pcm_cap,
                           size_t *pcm_len)
{
    size_t pos = 12;
    uint32_t sample_rate = 0;
    uint16_t channels = 0;
    uint16_t bits = 0;
    const unsigned char *data = NULL;
    size_t data_len = 0;

    if (wav_len < 44 || memcmp(wav, "RIFF", 4) != 0
        || memcmp(wav + 8, "WAVE", 4) != 0) {
        return -EPROTO;
    }

    while (pos + 8 <= wav_len) {
        const unsigned char *chunk = wav + pos;
        uint32_t chunk_len = read_le32(chunk + 4);
        size_t next = pos + 8 + chunk_len + (chunk_len & 1U);
        if (next > wav_len) {
            return -EPROTO;
        }
        if (memcmp(chunk, "fmt ", 4) == 0 && chunk_len >= 16) {
            const unsigned char *fmt = chunk + 8;
            if (read_le16(fmt) != 1) {
                return -ENOTSUP;
            }
            channels = read_le16(fmt + 2);
            sample_rate = read_le32(fmt + 4);
            bits = read_le16(fmt + 14);
        } else if (memcmp(chunk, "data", 4) == 0) {
            data = chunk + 8;
            data_len = chunk_len;
        }
        pos = next;
    }

    if (!data || channels != 1 || bits != 16 || sample_rate == 0) {
        return -EPROTO;
    }
    if (sample_rate != AGENT_MIMO_TTS_SAMPLE_RATE) {
        syslog(LOG_ERR, "[%s] TTS sample rate %lu unsupported\n",
            TAG, (unsigned long)sample_rate);
        return -ENOTSUP;
    }
    if (data_len > pcm_cap) {
        return -ENOSPC;
    }

    memcpy(pcm_out, data, data_len);
    *pcm_len = data_len;
    return 0;
}

static int mimo_tts_init(void)
{
    return mimo_asr_init();
}

static int mimo_tts_synthesize(const char *text,
                               unsigned char *pcm_out,
                               size_t pcm_cap,
                               size_t *pcm_len)
{
    char *body = NULL;
    char *response = NULL;
    const char *audio_b64 = NULL;
    unsigned char *wav = NULL;
    size_t wav_cap;
    size_t wav_len = 0;
    size_t decoded_len = 0;
    cJSON *root = NULL;
    int ret;

    if (!text || text[0] == '\0' || !pcm_out || !pcm_len) {
        return -EINVAL;
    }

    ret = make_tts_body(text, &body);
    if (ret < 0) {
        return ret;
    }
    response = calloc(1, AGENT_MIMO_HTTP_RESP_BYTES);
    if (!response) {
        free(body);
        return -ENOMEM;
    }

    ret = post_mimo(body, response, AGENT_MIMO_HTTP_RESP_BYTES);
    free(body);
    if (ret < 0) {
        free(response);
        return ret;
    }

    root = cJSON_Parse(response);
    free(response);
    if (!root) {
        return -EPROTO;
    }
    ret = json_audio_data(root, &audio_b64);
    if (ret < 0) {
        cJSON_Delete(root);
        return ret;
    }

    wav_cap = (strlen(audio_b64) * 3) / 4 + 4;
    wav = malloc(wav_cap);
    if (!wav) {
        return -ENOMEM;
    }
    ret = mbedtls_base64_decode(wav, wav_cap, &wav_len,
        (const unsigned char *)audio_b64, strlen(audio_b64));
    cJSON_Delete(root);
    if (ret != 0) {
        free(wav);
        return -EPROTO;
    }

    ret = extract_wav_pcm(wav, wav_len, pcm_out, pcm_cap, &decoded_len);
    free(wav);
    if (ret == 0) {
        *pcm_len = decoded_len;
        syslog(LOG_INFO, "[%s] TTS PCM bytes=%zu\n", TAG, decoded_len);
    }
    return ret;
}
