        /* MiMo is the default backend for the contest voice path. */
        mimo_tts_register();
        mimo_asr_register();
        /* Keep Volcengine available for compatibility and fallback. */
        volc_tts_register();
        volc_asr_register();
        s_backends_registered = 1;
    }

    return 0;
}

