/* ── Streaming HTTP response reader ─────────────────────────── */

enum stream_chunk_state {
    STREAM_CHUNK_SIZE = 0,
    STREAM_CHUNK_DATA,
    STREAM_CHUNK_DATA_CR,
    STREAM_CHUNK_DATA_LF,
    STREAM_CHUNK_TRAILER,
    STREAM_CHUNK_DONE,
};

struct stream_chunk_parser {
    enum stream_chunk_state state;
    char line[64];
    size_t line_len;
    uint64_t remaining;
    bool line_cr;
};

static int stream_chunk_parse_line(struct stream_chunk_parser *parser)
{
    char *endptr;
    char *semi;
    unsigned long long chunk_size;

    if (parser->state == STREAM_CHUNK_TRAILER) {
        if (parser->line_len == 0) {
            parser->state = STREAM_CHUNK_DONE;
        }
        parser->line_len = 0;
        return 0;
    }

    if (parser->line_len == 0) {
        return VELA_TLS_ERR_READ;
    }

    parser->line[parser->line_len] = '\0';
    semi = strchr(parser->line, ';');
    if (semi) {
        *semi = '\0';
    }

    endptr = NULL;
    chunk_size = strtoull(parser->line, &endptr, 16);
    if (endptr == parser->line || *endptr != '\0'
        ) {
        return VELA_TLS_ERR_READ;
    }

    parser->remaining = (uint64_t)chunk_size;
    parser->state = chunk_size == 0 ? STREAM_CHUNK_TRAILER
                                    : STREAM_CHUNK_DATA;
    parser->line_len = 0;
    return 0;
}

static int stream_chunk_feed(struct stream_chunk_parser *parser,
    const unsigned char *data, size_t len, vela_https_body_cb_t body_cb,
    void *user_data)
{
    while (len > 0 && parser->state != STREAM_CHUNK_DONE) {
        unsigned char c;
        size_t take;
        int ret;

        switch (parser->state) {
        case STREAM_CHUNK_SIZE:
        case STREAM_CHUNK_TRAILER:
            c = *data++;
            len--;
            if (parser->line_cr) {
                if (c != '\n') {
                    return VELA_TLS_ERR_READ;
                }
                parser->line_cr = false;
                ret = stream_chunk_parse_line(parser);
                if (ret < 0) {
                    return ret;
                }
                continue;
            }
            if (c == '\r') {
                parser->line_cr = true;
                continue;
            }
            if (c == '\n') {
                ret = stream_chunk_parse_line(parser);
                if (ret < 0) {
                    return ret;
                }
                continue;
            }
            if (parser->line_len >= sizeof(parser->line) - 1) {
                return VELA_TLS_ERR_OVERFLOW;
            }
            parser->line[parser->line_len++] = (char)c;
            continue;

        case STREAM_CHUNK_DATA:
            take = len;
            if ((uint64_t)take > parser->remaining) {
                take = (size_t)parser->remaining;
            }
            if (take > 0) {
                ret = body_cb(data, take, user_data);
                if (ret < 0) {
                    return ret;
                }
                data += take;
                len -= take;
                parser->remaining -= (uint64_t)take;
            }
            if (parser->remaining == 0) {
                parser->state = STREAM_CHUNK_DATA_CR;
            }
            continue;

        case STREAM_CHUNK_DATA_CR:
            if (*data++ != '\r') {
                return VELA_TLS_ERR_READ;
            }
            len--;
            parser->state = STREAM_CHUNK_DATA_LF;
            continue;

        case STREAM_CHUNK_DATA_LF:
            if (*data++ != '\n') {
                return VELA_TLS_ERR_READ;
            }
            len--;
            parser->state = STREAM_CHUNK_SIZE;
            continue;

        case STREAM_CHUNK_DONE:
            break;
        }
    }

    return 0;
}

static int tls_read_response_stream(tls_ctx_t *ctx,
    vela_https_body_cb_t body_cb, void *user_data, bool *out_keep_alive)
{
    unsigned char body_buf[2048];
    struct stream_chunk_parser chunk_parser;
    char *raw = tls_raw_acquire();
    size_t raw_len = 0;
    size_t initial_len;
    size_t consumed;
    long long content_length = -1;
    bool chunked = false;
    bool eof = false;
    int http_status = 0;
    int ret;

    if (!body_cb) {
        tls_raw_release(raw);
        return VELA_TLS_ERR_READ;
    }

    memset(&chunk_parser, 0, sizeof(chunk_parser));
    chunk_parser.state = STREAM_CHUNK_SIZE;

    while (!eof && raw_len < TLS_RAW_BUF_SIZE - 1) {
        ret = mbedtls_ssl_read(&ctx->ssl,
            (unsigned char *)(raw + raw_len), TLS_RAW_BUF_SIZE - 1 - raw_len);
        if (ret > 0) {
            raw_len += (size_t)ret;
            if (memmem(raw, raw_len, "\r\n\r\n", 4)) {
                break;
            }
        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
            eof = true;
        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
            syslog(LOG_ERR, "[%s] ssl_read (stream header) ret=0x%x\n",
                TAG, -ret);
            tls_raw_release(raw);
            return VELA_TLS_ERR_READ;
        }
    }

    raw[raw_len] = '\0';
    if (sscanf(raw, "HTTP/1.%*d %d", &http_status) != 1) {
        syslog(LOG_ERR, "[%s] Failed to parse streaming HTTP status\n", TAG);
        tls_raw_release(raw);
        return VELA_TLS_ERR_READ;
    }

    char *body_start = (char *)memmem(raw, raw_len, "\r\n\r\n", 4);
    if (!body_start) {
        tls_raw_release(raw);
        return http_status;
    }

    if (out_keep_alive) {
        *out_keep_alive = true;
        char *conn_hdr = strcasestr(raw, "Connection:");
        if (conn_hdr && conn_hdr < body_start) {
            *out_keep_alive = strcasestr(conn_hdr, "keep-alive") != NULL;
        }
    }

    {
        char *cl_hdr = strcasestr(raw, "Content-Length:");
        if (cl_hdr && cl_hdr < body_start) {
            cl_hdr += strlen("Content-Length:");
            content_length = strtoll(cl_hdr, NULL, 10);
            if (content_length < 0) {
                content_length = -1;
            }
        }
    }

    {
        char *te_hdr = strcasestr(raw, "Transfer-Encoding:");
        if (te_hdr && te_hdr < body_start) {
            chunked = strcasestr(te_hdr, "chunked") != NULL;
        }
    }

    body_start += 4;
    initial_len = (size_t)(raw + raw_len - body_start);
    consumed = 0;

    if (chunked) {
        ret = stream_chunk_feed(&chunk_parser,
            (const unsigned char *)body_start, initial_len, body_cb,
            user_data);
        if (ret < 0) {
            tls_raw_release(raw);
            return ret;
        }
    } else {
        size_t take = initial_len;
        if (content_length >= 0
            && (long long)take > content_length) {
            take = (size_t)content_length;

            take = (size_t)content_length;
        }
        if (take > 0) {
            ret = body_cb((const unsigned char *)body_start, take, user_data);
            if (ret < 0) {
                tls_raw_release(raw);
                return ret;
            }
            consumed = take;
        }
    }

    tls_raw_release(raw);

    if (chunked) {
        while (chunk_parser.state != STREAM_CHUNK_DONE) {
            ret = mbedtls_ssl_read(&ctx->ssl, body_buf, sizeof(body_buf));
            if (ret > 0) {
                ret = stream_chunk_feed(&chunk_parser, body_buf,
                    (size_t)ret, body_cb, user_data);
                if (ret < 0) {
                    return ret;
                }
            } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
                return VELA_TLS_ERR_READ;
            } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
                return VELA_TLS_ERR_READ;
            }
        }
    } else if (content_length >= 0) {
        while ((long long)consumed < content_length) {
            size_t want = sizeof(body_buf);
            long long remain = content_length - (long long)consumed;
            if ((long long)want > remain) {
                want = (size_t)remain;
            }
            ret = mbedtls_ssl_read(&ctx->ssl, body_buf, want);
            if (ret > 0) {
                int body_ret = body_cb(body_buf, (size_t)ret, user_data);
                if (body_ret < 0) {
                    return body_ret;
                }
                consumed += (size_t)ret;
            } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
                return VELA_TLS_ERR_READ;
            } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
                return VELA_TLS_ERR_READ;
            }
        }
    } else {
        if (out_keep_alive) {
            *out_keep_alive = false;
        }
        while (1) {
            ret = mbedtls_ssl_read(&ctx->ssl, body_buf, sizeof(body_buf));
            if (ret > 0) {
                ret = body_cb(body_buf, (size_t)ret, user_data);
                if (ret < 0) {
                    return ret;
                }
            } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
                break;
            } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
                return VELA_TLS_ERR_READ;
            }
        }
    }

    return http_status;
}

