   427	static int board_i2s_read_block(audio_capture_t* cap, void* buf,
   428	    size_t cap_len, size_t* nbytes_out)
   429	{
   430	    struct audio_buf_desc_s desc;
   431	    struct ap_buffer_s* apb = NULL;
   432	    size_t request = cap_len;
   433	    int ret;
   434	
   435	    /* voice_channel_start() deliberately starts the reader thread before
   436	     * enabling the device.  Let that short hand-off window be retried by the
   437	     * reader instead of submitting to a stopped I2S stream (which returns
   438	     * -EBUSY from the contest lower half). */
   439	    if (!cap->started) {
   440	        return -EAGAIN;
   441	    }
   442	
   443	    if (request > BOARD_I2S_CAPTURE_BLOCK_BYTES) {
   444	        request = BOARD_I2S_CAPTURE_BLOCK_BYTES;
   445	    }
   446	    request -= request % cap->out_frame_bytes;
   447	    if (request == 0) {
   448	        return -EINVAL;
   449	    }
   450	
   451	    memset(&desc, 0, sizeof(desc));
   452	    desc.numbytes = request;
   453	    desc.u.pbuffer = &apb;
   454	    ret = apb_alloc(&desc);
   455	    if (ret < 0) {
   456	        return ret;
   457	    }
   458	
   459	    while (nxsem_trywait(&cap->i2s_done) == 0)
   460	        ;
   461	
   462	    cap->i2s_apb = apb;
   463	    cap->i2s_nbytes = 0;
   464	    cap->i2s_result = -EINPROGRESS;
   465	    cap->i2s_pending = 1;
   466	    ret = I2S_RECEIVE(cap->i2s, apb, board_i2s_capture_done, cap,
   467	        MSEC2TICK(BOARD_I2S_CAPTURE_TIMEOUT_MS));
   468	    if (ret < 0) {
   469	        cap->i2s_pending = 0;
   470	        cap->i2s_apb = NULL;
   471	        apb_free(apb);
   472	        return ret;
   473	    }
   474	
   475	    /* I2S completion owns the lower-half APB reference.  Do not release the
   476	     * application's reference on a timeout: a late callback would otherwise
   477	     * access a freed capture object.  audio_capture_abort() issues STOP,
   478	     * which completes this wait with the driver's cancellation result. */
   479	    ret = nxsem_wait_uninterruptible(&cap->i2s_done);
   480	
   481	    if (ret >= 0) {
   482	        ret = cap->i2s_result;
   483	    }
   484	
   485	    if (ret >= 0 && cap->i2s_nbytes > 0) {
   486	        size_t nbytes = cap->i2s_nbytes;
   487	
   488	        if (nbytes > request) {
   489	            ret = -EIO;
   490	        } else {
   491	            memcpy(buf, apb->samp, nbytes);
   492	            *nbytes_out = nbytes;
   493	        }
   494	    }
   495	
   496	    cap->i2s_pending = 0;
   497	    cap->i2s_apb = NULL;
   498	    apb_free(apb);
   499	    return ret;
   500	}
