   692	/* ── Streaming HTTP response reader ─────────────────────────── */
   693	
   694	enum stream_chunk_state {
   695	    STREAM_CHUNK_SIZE = 0,
   696	    STREAM_CHUNK_DATA,
   697	    STREAM_CHUNK_DATA_CR,
   698	    STREAM_CHUNK_DATA_LF,
   699	    STREAM_CHUNK_TRAILER,
   700	    STREAM_CHUNK_DONE,
   701	};
   702	
   703	struct stream_chunk_parser {
   704	    enum stream_chunk_state state;
   705	    char line[64];
   706	    size_t line_len;
   707	    uint64_t remaining;
   708	    bool line_cr;
   709	};
   710	
   711	static int stream_chunk_parse_line(struct stream_chunk_parser *parser)
   712	{
   713	    char *endptr;
   714	    char *semi;
   715	    unsigned long long chunk_size;
   716	
   717	    if (parser->state == STREAM_CHUNK_TRAILER) {
   718	        if (parser->line_len == 0) {
   719	            parser->state = STREAM_CHUNK_DONE;
   720	        }
   721	        parser->line_len = 0;
   722	        return 0;
   723	    }
   724	
   725	    if (parser->line_len == 0) {
   726	        return VELA_TLS_ERR_READ;
   727	    }
   728	
   729	    parser->line[parser->line_len] = '\0';
   730	    semi = strchr(parser->line, ';');
   731	    if (semi) {
   732	        *semi = '\0';
   733	    }
   734	
   735	    endptr = NULL;
   736	    chunk_size = strtoull(parser->line, &endptr, 16);
   737	    if (endptr == parser->line || *endptr != '\0') {
   738	        return VELA_TLS_ERR_READ;
   739	    }
   740	
   741	    parser->remaining = (uint64_t)chunk_size;
   742	    parser->state = chunk_size == 0 ? STREAM_CHUNK_TRAILER
   743	                                    : STREAM_CHUNK_DATA;
   744	    parser->line_len = 0;
   745	    return 0;
   746	}
   747	
   748	static int stream_chunk_feed(struct stream_chunk_parser *parser,
   749	    const unsigned char *data, size_t len, vela_https_body_cb_t body_cb,
   750	    void *user_data)
   751	{
   752	    while (len > 0 && parser->state != STREAM_CHUNK_DONE) {
   753	        unsigned char c;
   754	        size_t take;
   755	        int ret;
   756	
   757	        switch (parser->state) {
   758	        case STREAM_CHUNK_SIZE:
   759	        case STREAM_CHUNK_TRAILER:
   760	            c = *data++;
   761	            len--;
   762	            if (parser->line_cr) {
   763	                if (c != '\n') {
   764	                    return VELA_TLS_ERR_READ;
   765	                }
   766	                parser->line_cr = false;
   767	                ret = stream_chunk_parse_line(parser);
   768	                if (ret < 0) {
   769	                    return ret;
   770	                }
   771	                continue;
   772	            }
   773	            if (c == '\r') {
   774	                parser->line_cr = true;
   775	                continue;
   776	            }
   777	            if (c == '\n') {
   778	                ret = stream_chunk_parse_line(parser);
   779	                if (ret < 0) {
   780	                    return ret;
   781	                }
   782	                continue;
   783	            }
   784	            if (parser->line_len >= sizeof(parser->line) - 1) {
   785	                return VELA_TLS_ERR_OVERFLOW;
   786	            }
   787	            parser->line[parser->line_len++] = (char)c;
   788	            continue;
   789	
   790	        case STREAM_CHUNK_DATA:
   791	            take = len;
   792	            if ((uint64_t)take > parser->remaining) {
   793	                take = (size_t)parser->remaining;
   794	            }
   795	            if (take > 0) {
   796	                ret = body_cb(data, take, user_data);
   797	                if (ret < 0) {
   798	                    return ret;
   799	                }
   800	                data += take;
   801	                len -= take;
   802	                parser->remaining -= (uint64_t)take;
   803	            }
   804	            if (parser->remaining == 0) {
   805	                parser->state = STREAM_CHUNK_DATA_CR;
   806	            }
   807	            continue;
   808	
   809	        case STREAM_CHUNK_DATA_CR:
   810	            if (*data++ != '\r') {
   811	                return VELA_TLS_ERR_READ;
   812	            }
   813	            len--;
   814	            parser->state = STREAM_CHUNK_DATA_LF;
   815	            continue;
   816	
   817	        case STREAM_CHUNK_DATA_LF:
   818	            if (*data++ != '\n') {
   819	                return VELA_TLS_ERR_READ;
   820	            }
   821	            len--;
   822	            parser->state = STREAM_CHUNK_SIZE;
   823	            continue;
   824	
   825	        case STREAM_CHUNK_DONE:
   826	            break;
   827	        }
   828	    }
   829	
   830	    return 0;
   831	}
