   833	static int tls_read_response_stream(tls_ctx_t *ctx,
   834	    vela_https_body_cb_t body_cb, void *user_data, bool *out_keep_alive)
   835	{
   836	    unsigned char body_buf[2048];
   837	    struct stream_chunk_parser chunk_parser;
   838	    char *raw = tls_raw_acquire();
   839	    size_t raw_len = 0;
   840	    size_t initial_len;
   841	    size_t consumed;
   842	    long long content_length = -1;
   843	    bool chunked = false;
   844	    bool eof = false;
   845	    int http_status = 0;
   846	    int ret;
   847	
   848	    if (!body_cb) {
   849	        tls_raw_release(raw);
   850	        return VELA_TLS_ERR_READ;
   851	    }
   852	
   853	    memset(&chunk_parser, 0, sizeof(chunk_parser));
   854	    chunk_parser.state = STREAM_CHUNK_SIZE;
   855	
   856	    while (!eof && raw_len < TLS_RAW_BUF_SIZE - 1) {
   857	        ret = mbedtls_ssl_read(&ctx->ssl,
   858	            (unsigned char *)(raw + raw_len), TLS_RAW_BUF_SIZE - 1 - raw_len);
   859	        if (ret > 0) {
   860	            raw_len += (size_t)ret;
   861	            if (memmem(raw, raw_len, "\r\n\r\n", 4)) {
   862	                break;
   863	            }
   864	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
   865	            eof = true;
   866	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
   867	            syslog(LOG_ERR, "[%s] ssl_read (stream header) ret=0x%x\n",
   868	                TAG, -ret);
   869	            tls_raw_release(raw);
   870	            return VELA_TLS_ERR_READ;
   871	        }
   872	    }
   873	
   874	    raw[raw_len] = '\0';
   875	    if (sscanf(raw, "HTTP/1.%*d %d", &http_status) != 1) {
   876	        syslog(LOG_ERR, "[%s] Failed to parse streaming HTTP status\n", TAG);
   877	        tls_raw_release(raw);
   878	        return VELA_TLS_ERR_READ;
   879	    }
   880	
   881	    char *body_start = (char *)memmem(raw, raw_len, "\r\n\r\n", 4);
   882	    if (!body_start) {
   883	        tls_raw_release(raw);
   884	        return http_status;
   885	    }
   886	
   887	    if (out_keep_alive) {
   888	        *out_keep_alive = true;
   889	        char *conn_hdr = strcasestr(raw, "Connection:");
   890	        if (conn_hdr && conn_hdr < body_start) {
   891	            *out_keep_alive = strcasestr(conn_hdr, "keep-alive") != NULL;
   892	        }
   893	    }
   894	
   895	    {
   896	        char *cl_hdr = strcasestr(raw, "Content-Length:");
   897	        if (cl_hdr && cl_hdr < body_start) {
   898	            cl_hdr += strlen("Content-Length:");
   899	            content_length = strtoll(cl_hdr, NULL, 10);
   900	            if (content_length < 0) {
   901	                content_length = -1;
   902	            }
   903	        }
   904	    }
   905	
   906	    {
   907	        char *te_hdr = strcasestr(raw, "Transfer-Encoding:");
   908	        if (te_hdr && te_hdr < body_start) {
   909	            chunked = strcasestr(te_hdr, "chunked") != NULL;
   910	        }
   911	    }
   912	
   913	    body_start += 4;
   914	    initial_len = (size_t)(raw + raw_len - body_start);
   915	    consumed = 0;
   916	
   917	    if (chunked) {
   918	        ret = stream_chunk_feed(&chunk_parser,
   919	            (const unsigned char *)body_start, initial_len, body_cb,
   920	            user_data);
   921	        if (ret < 0) {
   922	            tls_raw_release(raw);
   923	            return ret;
   924	        }
   925	    } else {
   926	        size_t take = initial_len;
   927	        if (content_length >= 0
   928	            && (long long)take > content_length) {
   929	            take = (size_t)content_length;
   930	        }
   931	        if (take > 0) {
   932	            ret = body_cb((const unsigned char *)body_start, take, user_data);
   933	            if (ret < 0) {
   934	                tls_raw_release(raw);
   935	                return ret;
   936	            }
   937	            consumed = take;
   938	        }
   939	    }
   940	
   941	    tls_raw_release(raw);
   942	
   943	    if (chunked) {
   944	        while (chunk_parser.state != STREAM_CHUNK_DONE) {
   945	            ret = mbedtls_ssl_read(&ctx->ssl, body_buf, sizeof(body_buf));
   946	            if (ret > 0) {
   947	                ret = stream_chunk_feed(&chunk_parser, body_buf,
   948	                    (size_t)ret, body_cb, user_data);
   949	                if (ret < 0) {
   950	                    return ret;
   951	                }
   952	            } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
   953	                return VELA_TLS_ERR_READ;
   954	            } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
   955	                return VELA_TLS_ERR_READ;
   956	            }
   957	        }
   958	    } else if (content_length >= 0) {
   959	        while ((long long)consumed < content_length) {
   960	            size_t want = sizeof(body_buf);
   961	            long long remain = content_length - (long long)consumed;
   962	            if ((long long)want > remain) {
   963	                want = (size_t)remain;
   964	            }
   965	            ret = mbedtls_ssl_read(&ctx->ssl, body_buf, want);
   966	            if (ret > 0) {
   967	                int body_ret = body_cb(body_buf, (size_t)ret, user_data);
   968	                if (body_ret < 0) {
   969	                    return body_ret;
   970	                }
   971	                consumed += (size_t)ret;
   972	            } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
   973	                return VELA_TLS_ERR_READ;
   974	            } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
   975	                return VELA_TLS_ERR_READ;
   976	            }
   977	        }
   978	    } else {
   979	        if (out_keep_alive) {
   980	            *out_keep_alive = false;
   981	        }
   982	        while (1) {
   983	            ret = mbedtls_ssl_read(&ctx->ssl, body_buf, sizeof(body_buf));
   984	            if (ret > 0) {
   985	                ret = body_cb(body_buf, (size_t)ret, user_data);
   986	                if (ret < 0) {
   987	                    return ret;
   988	                }
   989	            } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
   990	                break;
   991	            } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
   992	                return VELA_TLS_ERR_READ;
   993	            }
   994	        }
   995	    }
   996	
   997	    return http_status;
   998	}
