  1002	static int vela_https_request_locked(
  1003	    const char* host,
  1004	    const char* port,
  1005	    const char* method,
  1006	    const char* path,
  1007	    const vela_header_t* headers,
  1008	    const char* body,
  1009	    size_t body_len,
  1010	    char* resp_buf,
  1011	    size_t resp_cap,
  1012	    size_t* out_body_len)
  1013	{
  1014	    int ret;
  1015	
  1016	    /* Try to get a pooled connection first */
  1017	    conn_slot_t* slot = pool_acquire(host, port);
  1018	
  1019	    if (slot && slot->valid) {
  1020	        /* Drain any leftover data from previous response before reuse.
  1021	         * Without this, a partially-read response body (e.g. truncated
  1022	         * chunked data) would be misinterpreted as the next HTTP status. */
  1023	        if (slot->ctx.net.fd >= 0) {
  1024	            unsigned char drain[512];
  1025	            int dr;
  1026	            /* Temporarily set a very short socket timeout to drain without blocking */
  1027	            struct timeval tv_drain = { .tv_sec = 0, .tv_usec = 10000 }; /* 10ms */
  1028	            struct timeval tv_orig = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
  1029	                .tv_usec = 0 };
  1030	            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
  1031	                &tv_drain, sizeof(tv_drain));
  1032	            while ((dr = mbedtls_ssl_read(&slot->ctx.ssl, drain, sizeof(drain))) > 0)
  1033	                ; /* discard leftover bytes */
  1034	            /* Restore original timeout */
  1035	            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
  1190	
  1191	        ret = tls_write_request(&slot->ctx, method, host, path, headers,
  1192	            body, body_len);
  1193	        if (ret == 0) {
  1194	            bool keep = false;
  1195	            ret = tls_read_response_stream(&slot->ctx, body_cb, user_data,
  1196	                &keep);
  1197	            if (ret > 0) {
  1198	                pool_release(slot, host, port, keep);
  1199	                return ret;
  1200	            }
  1201	        }
  1202	
  1203	stream_pool_reconnect:
  1204	        tls_ctx_free(&slot->ctx);
  1205	        slot->valid = false;
  1206	    }
  1207	
  1208	    if (!slot) {
  1209	        tls_ctx_t tmp_ctx;
  1210	        ret = tls_ctx_connect(&tmp_ctx, host, port);
  1211	        if (ret != 0) {
  1212	            tls_ctx_free(&tmp_ctx);
  1213	            return ret;
  1214	        }
  1215	        ret = tls_write_request(&tmp_ctx, method, host, path, headers,
  1216	            body, body_len);
  1217	        if (ret == 0) {
  1218	            ret = tls_read_response_stream(&tmp_ctx, body_cb, user_data,
  1219	                NULL);
  1220	        }
  1221	        tls_ctx_free(&tmp_ctx);
  1222	        return ret;
  1223	    }
  1224	
  1225	    ret = tls_ctx_connect(&slot->ctx, host, port);
  1226	    if (ret != 0) {
  1227	        pool_release(slot, host, port, false);
  1228	        return ret;
  1229	    }
  1230	    ret = tls_write_request(&slot->ctx, method, host, path, headers,
  1231	        body, body_len);
  1232	    if (ret != 0) {
  1233	        pool_release(slot, host, port, false);
  1234	        return ret;
  1235	    }
  1236	
  1237	    {
  1238	        bool keep = false;
  1239	        ret = tls_read_response_stream(&slot->ctx, body_cb, user_data,
  1240	            &keep);
  1241	        pool_release(slot, host, port, ret > 0 && keep);
  1242	    }
  1243	    return ret;
  1244	}
