1080	int voice_channel_speak(const char* text)
1081	{
1082	    if (!text || text[0] == '\0') {
1083	        return -EINVAL;
1084	    }
1085	
1086	    /* ── Serialize concurrent speak calls ── */
1087	    /* If another thread is already speaking, abort its TTS playback
1088	     * so we don't overlap media_player sessions (which causes the
1089	     * media framework to attempt a ~1.3GB allocation and crash). */
1090	    pthread_mutex_lock(&s_voice.lock);
1091	    if (s_voice.tts_pb) {
1092	        syslog(LOG_INFO, "[%s] speak: aborting previous TTS\n", TAG);
1093	        s_voice.tts_abort = 1;
1094	        audio_playback_stop(s_voice.tts_pb);
1095	    }
1096	    pthread_mutex_unlock(&s_voice.lock);
1097	
1098	    pthread_mutex_lock(&s_voice.speak_lock);
1099	
1100	    /* ── AEC workaround: reject TTS while PTT is recording ── */
1101	    pthread_mutex_lock(&s_voice.lock);
1102	    if (s_voice.state != VOICE_IDLE) {
1103	        pthread_mutex_unlock(&s_voice.lock);
1104	        pthread_mutex_unlock(&s_voice.speak_lock);
1105	        syslog(LOG_INFO,
1106	            "[%s] speak: skipped, recording active\n", TAG);
1107	        return -EBUSY;
1108	    }
1109	    pthread_mutex_unlock(&s_voice.lock);
1110	
1111	    /* Work on a mutable copy so we can strip markdown in-place */
1112	    size_t text_len = strlen(text);
1113	    char* clean = malloc(text_len + 1);
1114	
1115	    if (!clean) {
1116	        pthread_mutex_unlock(&s_voice.speak_lock);
1117	        return -ENOMEM;
1118	    }
1119	
1120	    memcpy(clean, text, text_len + 1);
1121	    tts_strip_markdown(clean);
1122	
1123	    /* If stripping left nothing, bail out */
1124	    if (clean[0] == '\0') {
1125	        free(clean);
1126	        pthread_mutex_unlock(&s_voice.speak_lock);
1127	        return 0;
1128	    }
1129	
1130	    syslog(LOG_INFO, "[%s] speak: \"%.*s\" (%zu bytes)\n",
1131	        TAG, 60, clean, strlen(clean));
1132	
1133	    clock_gettime(CLOCK_MONOTONIC, &s_tts_start);
1134	    s_tts_first_chunk = 0;
1135	
1136	    if (s_asr_done_ts.tv_sec > 0) {
1137	        long llm_ms = (s_tts_start.tv_sec - s_asr_done_ts.tv_sec) * 1000
1138	            + (s_tts_start.tv_nsec - s_asr_done_ts.tv_nsec) / 1000000;
1139	        syslog(LOG_INFO, "[%s] LLM latency: %ldms\n", TAG, llm_ms);
1140	    }
1141	
1142	    /* Try streaming TTS first (callback per chunk) */
1143	    audio_playback_t* pb = audio_playback_open(
1144	        AGENT_AUDIO_PLAYBACK_DEV,
1145	        AGENT_TTS_WS_SAMPLE_RATE,
1146	        AGENT_VOICE_CHANNELS,
1147	        AGENT_VOICE_BITS);
1148	
1149	    if (!pb) {
