1153	        return -EIO;
1154	    }
1155	
1156	    /* Register active playback so voice_channel_start() can abort it */
1157	    pthread_mutex_lock(&s_voice.lock);
1158	    s_voice.tts_abort = 0;
1159	    s_voice.tts_pb = pb;
1160	    pthread_mutex_unlock(&s_voice.lock);
1161	
1162	    /* Use streaming TTS: each chunk writes to playback file */
1163	    int ret = voice_tts_speak_stream(clean,
1164	        tts_stream_cb, pb);
1165	
1166	    struct timespec tts_net;
1167	    clock_gettime(CLOCK_MONOTONIC, &tts_net);
1168	    long net_ms = (tts_net.tv_sec - s_tts_start.tv_sec) * 1000
1169	        + (tts_net.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1170	    syslog(LOG_INFO, "[%s] TTS network done: %ldms\n", TAG, net_ms);
