 247	int audio_playback_write(audio_playback_t* pb, const void* buf, size_t len)
 248	{
 249	    if (!pb || !buf || len == 0) {
 250	        return -EINVAL;
 251	    }
 252	
 253	    if (pb->stopped) {
 254	        return -ECANCELED;
 255	    }
 256	
 257	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_295_VOICE_ECHO
 258	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_BOARD_I2S) {
 259	        const unsigned char* src = buf;
 260	        size_t total = 0;
 261	
 262	        len -= len % (size_t)pb->bytes_per_frame;
 263	        while (total < len) {
 264	            size_t block = len - total;
 265	            int ret;
 266	
 267	            if (block > BOARD_I2S_PLAYBACK_BLOCK_BYTES) {
 268	                block = BOARD_I2S_PLAYBACK_BLOCK_BYTES;
 269	            }
 270	            block -= block % (size_t)pb->bytes_per_frame;
 271	            ret = board_i2s_write_block(pb, src + total, block);
 272	            if (ret < 0) {
 273	                return total > 0 ? (int)total : ret;
 274	            }
 275	            total += block;
 276	        }
 277	
 278	        pb->total_written += total;
 279	        return (int)total;
 280	    }
 281	#endif
 282	
 283	    if (pb->backend != AUDIO_PLAYBACK_BACKEND_MEDIA_PLAYER || !pb->player) {
 284	        return -EINVAL;
 285	    }
 286	
 287	    ssize_t n = media_player_write_data(pb->player, buf, len);
 288	    if (n > 0) {
 289	        pb->total_written += (size_t)n;
 290	    }
 291	
 292	    return (int)n;
 293	}
